import {updateSearchParams} from '@github-ui/history'
import {ssrSafeLocation} from '@github-ui/ssr-utils'
import {useCallback, useMemo, useState} from 'react'

interface UsePaginationOptions {
  pageSize?: number
  paramName?: string
}

interface UsePaginationReturn<T> {
  currentPage: number
  totalPages: number
  paginatedItems: T[]
  navigateToPage: (page: number) => void
  pageSize: number
}

export function usePagination<T>(items: T[], options: UsePaginationOptions = {}): UsePaginationReturn<T> {
  const {pageSize = 20, paramName = 'page'} = options
  const [currentPage, setCurrentPage] = useState(() =>
    Math.max(1, Number(new URLSearchParams(ssrSafeLocation.search).get(paramName)) || 1),
  )

  const totalPages = Math.ceil(items.length / pageSize)

  const paginatedItems = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize
    const endIndex = startIndex + pageSize
    return items.slice(startIndex, endIndex)
  }, [items, currentPage, pageSize])

  // Helper function to update page in URL and trigger re-render
  const navigateToPage = useCallback(
    (page: number) => {
      const clamped = Math.max(1, Number.isFinite(page) ? page : 1)
      setCurrentPage(clamped)
      const newSearchParams = new URLSearchParams(ssrSafeLocation.search)
      newSearchParams.set(paramName, clamped.toString())
      updateSearchParams(newSearchParams)
    },
    [paramName],
  )

  return {
    currentPage,
    totalPages,
    paginatedItems,
    navigateToPage,
    pageSize,
  }
}
