import {ActionList, ActionMenu, Banner, Breadcrumbs, Button, Heading, LinkButton, Stack} from '@primer/react'
import {DownloadIcon, TriangleDownIcon} from '@primer/octicons-react'
import {useNavigation} from '@github-ui/licensing-common/contexts/NavigationContext'
import {useState} from 'react'
import {useCreateCSV} from '@github-ui/licensing-common/hooks/useCreateCSV'
import {MemoryExportsDialog} from '@github-ui/copilot-memory-exports'
import {MemoryAdminDeleteDialog} from '@github-ui/copilot-for-business/components/MemoryAdminDeleteDialog'

interface CopilotLicensingHeaderProps {
  policiesPath?: string
  entityName?: string
  memoryExportUrl?: string | null
  memoryExportVisible?: boolean
  memoryAdminDeleteUrl?: string | null
}

export function CopilotLicensingHeader({
  policiesPath,
  entityName,
  memoryExportUrl,
  memoryExportVisible,
  memoryAdminDeleteUrl,
}: CopilotLicensingHeaderProps) {
  const {basePath, slug} = useNavigation()
  const licensingLink = `${basePath}/licensing`
  const csvActivityDownloadUrl = `${basePath}/settings/download_seat_management_activity`
  const policiesLink = policiesPath ?? `${basePath}/settings/copilot?tab=policies`
  const displayEntityName = entityName ?? slug
  const [showBanner, setShowBanner] = useState(false)
  const [bannerMessage, setBannerMessage] = useState('')
  const [bannerTitle, setBannerTitle] = useState<'CSV Export in Progress' | 'CSV Export Error'>(
    'CSV Export in Progress',
  )
  const [bannerVariant, setBannerVariant] = useState<'critical' | 'success'>('critical')
  const [memoryExportsDialogOpen, setMemoryExportsDialogOpen] = useState(false)
  const [memoryAdminDeleteDialogOpen, setMemoryAdminDeleteDialogOpen] = useState(false)

  const showMemoryExportsMenuItem = !!memoryExportVisible && !!memoryExportUrl
  const showMemoryAdminDeleteMenuItem = !!memoryAdminDeleteUrl
  const showActionMenu = showMemoryExportsMenuItem || showMemoryAdminDeleteMenuItem

  const handleResult = (result: string) => {
    if (result === 'success') {
      setBannerMessage(
        'Your activity report is being generated. You will receive an email when it is ready to download.',
      )
      setBannerTitle('CSV Export in Progress')
      setBannerVariant('success')
    } else {
      setBannerMessage('An error occurred while exporting the CSV report.')
      setBannerTitle('CSV Export Error')
      setBannerVariant('critical')
    }
    setShowBanner(true)
  }

  const {loading: activityLoading, makeCSVRequest: activityDownload} = useCreateCSV({
    slug,
    endpoint: csvActivityDownloadUrl,
    async: true,
    method: 'GET',
    onSuccess: () => handleResult('success'),
  })

  return (
    <>
      {showBanner && (
        <Banner
          title={bannerTitle}
          hideTitle
          variant={bannerVariant}
          onDismiss={() => setShowBanner(false)}
          className="tmp-mb-3"
          data-testid="csv-download-banner"
        >
          {bannerMessage}
        </Banner>
      )}
      <Breadcrumbs>
        <Breadcrumbs.Item href={licensingLink}>Licensing</Breadcrumbs.Item>
        <Breadcrumbs.Item selected>Copilot</Breadcrumbs.Item>
      </Breadcrumbs>
      <Stack
        wrap="wrap"
        justify="space-between"
        direction="horizontal"
        className="mt-2 tmp-mb-3"
        data-testid="licensing-copilot-header"
      >
        <Heading as="h1">Copilot</Heading>
        <Stack direction="horizontal">
          <LinkButton className="fgColor-accent" variant="invisible" href={policiesLink}>
            View policies
          </LinkButton>
          {showActionMenu ? (
            <ActionMenu>
              <ActionMenu.Anchor>
                <Button
                  leadingVisual={DownloadIcon}
                  trailingVisual={TriangleDownIcon}
                  data-testid="download-actions-button"
                >
                  Get reports
                </Button>
              </ActionMenu.Anchor>
              <ActionMenu.Overlay>
                <ActionList>
                  <ActionList.Item
                    onSelect={() => {
                      void activityDownload()
                    }}
                    disabled={activityLoading}
                    data-testid="download-activity-report-menu-item"
                  >
                    Get activity report
                    <ActionList.Description variant="block">
                      Copilot usage activity for billed seats
                    </ActionList.Description>
                  </ActionList.Item>
                  {showMemoryExportsMenuItem && (
                    <ActionList.Item
                      onSelect={() => setMemoryExportsDialogOpen(true)}
                      data-testid="download-user-memories-menu-item"
                    >
                      Download user memories
                      <ActionList.Description variant="block">
                        User-scoped Copilot memories for all billed seats
                      </ActionList.Description>
                    </ActionList.Item>
                  )}
                  {showMemoryAdminDeleteMenuItem && (
                    <ActionList.Item
                      variant="danger"
                      onSelect={() => setMemoryAdminDeleteDialogOpen(true)}
                      data-testid="licensing-copilot-memory-admin-delete-menu-item"
                    >
                      Delete user memories
                      <ActionList.Description variant="block">
                        Permanently delete user-scoped Copilot memories for all licensed users
                      </ActionList.Description>
                    </ActionList.Item>
                  )}
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          ) : (
            <Button
              leadingVisual={DownloadIcon}
              onClick={activityDownload}
              loading={activityLoading}
              disabled={activityLoading}
              data-testid="download-csv-button"
            >
              Get activity report
            </Button>
          )}
        </Stack>
      </Stack>
      {showMemoryExportsMenuItem && (
        <MemoryExportsDialog
          isOpen={memoryExportsDialogOpen}
          onClose={() => setMemoryExportsDialogOpen(false)}
          entityName={displayEntityName}
          entityType="enterprise"
          memoryExportUrl={memoryExportUrl}
        />
      )}
      {showMemoryAdminDeleteMenuItem && (
        <MemoryAdminDeleteDialog
          isOpen={memoryAdminDeleteDialogOpen}
          onClose={() => setMemoryAdminDeleteDialogOpen(false)}
          entityName={displayEntityName}
          memoryDeleteUrl={memoryAdminDeleteUrl}
        />
      )}
    </>
  )
}
